hudson.tasks.Shell.command:
#!/usr/bin/env bash set -euo pipefail
LOG_TS() { date +"%Y-%m-%dT%H:%M:%S%z"; } log() { echo "[$(LOG_TS)] INFO $*" >&2; } warn() { echo "[$(LOG_TS)] WARN $*" >&2; } error() { echo "[$(LOG_TS)] ERROR $*" >&2; }
need() { command -v "$1" >/dev/null 2>&1 || { error "Missing required command: $1"; exit 2; }; }
cleanup() { local rc=$? local cmd="${BASH_COMMAND:-}" local line="${BASH_LINENO[0]:-}"
if [[ $rc -eq 0 ]]; then log "EXIT rc=0 (success). Cleaning AWS env vars." else error "EXIT rc=${rc} at line=${line} cmd=${cmd}. Cleaning AWS env vars." fi
unset AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY AWS_SESSION_TOKEN } on_err() { local rc=$? local line="${BASH_LINENO[0]:-}" local cmd="${BASH_COMMAND:-}" error "ERR rc=${rc} at line=${line} cmd=${cmd}" return $rc } trap on_err ERR trap cleanup EXIT
already_in_role() { local role_arn="$1" local role_name role_name="$(printf '%s' "$role_arn" | awk -F'/' '{print $NF}')" local caller_arn caller_arn="$(aws sts get-caller-identity --query Arn --output text 2>/dev/null || true)" [[ -n "$caller_arn" && "$caller_arn" == *":assumed-role/${role_name}/"* ]] }
assume_role() { local role_arn="${1:-${ROLE_ARN:-arn:aws:iam::736265540791:role/dbgap-etl}}" local session_name="${2:-${ROLE_SESSION_NAME:-s3-test}}" local duration="${3:-${ASSUME_DURATION_SECONDS:-900}}"
if already_in_role "$role_arn"; then log "Already running under role ${role_arn}; skipping AssumeRole" return 0 fi
log "Assuming role ${role_arn} (session=${session_name}, duration=${duration}s)" local assume_json assume_json="$(mktemp)"
aws sts assume-role \ --duration-seconds "$duration" \ --role-arn "$role_arn" \ --role-session-name "$session_name" \ > "$assume_json"
export AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY AWS_SESSION_TOKEN AWS_ACCESS_KEY_ID="$(jq -r '.Credentials.AccessKeyId' "$assume_json")" AWS_SECRET_ACCESS_KEY="$(jq -r '.Credentials.SecretAccessKey' "$assume_json")" AWS_SESSION_TOKEN="$(jq -r '.Credentials.SessionToken' "$assume_json")" rm -f "$assume_json" }
s3_cp() { local src="$1" dst="$2" required="${3:-true}" shift 3 || true if aws s3 cp "$src" "$dst" --no-progress --only-show-errors "$@"; then return 0 fi if [[ "$required" == "true" ]]; then error "S3 copy failed (required): $src -> $dst" return 1 fi warn "S3 copy failed (optional): $src -> $dst" return 0 }
reset_dir() { rm -rf "$1"; mkdir -p "$1"; }
# ----------------------------- # Prereqs # ----------------------------- need aws need jq need csvcut need csvformat need tail need java
: "${managed_inputs:?managed_inputs must be set (s3://.../Managed_Inputs.csv)}"
SRC_BUCKET="${SRC_BUCKET:-avillach-73-bdcatalyst-etl}" GLOBAL_ALLCONCEPTS_S3="${GLOBAL_ALLCONCEPTS_S3:-s3://${SRC_BUCKET}/general/completed/GLOBAL_allConcepts.csv}" INDEX_OUT_S3="${INDEX_OUT_S3:-s3://avillach-biodatacatalyst-deployments-3drb48r/genomic-etl/ingestion-indexes/}"
# ----------------------------- # Workspace # ----------------------------- reset_dir data reset_dir completed reset_dir logs
# ----------------------------- # Pull base inputs once # ----------------------------- assume_role "${ROLE_ARN:-arn:aws:iam::736265540791:role/dbgap-etl}" "s3-test" "900"
log "Downloading managed inputs -> data/Managed_Inputs.csv" s3_cp "$managed_inputs" "data/Managed_Inputs.csv" true
log "Downloading GLOBAL_allConcepts.csv -> data/GLOBAL_allConcepts.csv" s3_cp "$GLOBAL_ALLCONCEPTS_S3" "data/GLOBAL_allConcepts.csv" true
# ----------------------------- # Build genomic_inputs.csv # ----------------------------- log "Building genomic_inputs.csv" csvcut -c "Study Abbreviated Name","Study Identifier","Data Type","Data is ready to process","Data Processed" \ data/Managed_Inputs.csv > genomic_inputs.csv
log "genomic_inputs.csv preview:" head -n 10 genomic_inputs.csv >&2 || true
# ----------------------------- # Per-study downloads (sequential) # ----------------------------- download_study_files() { local abv_name="$1" stdy_id="$2"
local abv_lc abv_uc abv_lc="$(printf '%s' "$abv_name" | tr '[:upper:]' '[:lower:]')" abv_uc="$(printf '%s' "$abv_name" | tr '[:lower:]' '[:upper:]')"
log "${stdy_id} ready; fetching MULTI + patient mapping for ${abv_name}"
aws s3 cp "s3://${SRC_BUCKET}/${abv_lc}/rawData/" "data/" \ --recursive --exclude "*" --no-progress --only-show-errors \ --include "*${stdy_id}*Sample.MULTI*" --include "*${stdy_id}*sample.MULTI*" \ --include "*${stdy_id}*Sample.Multi*" --include "*${stdy_id}*sample.multi*" \ || { error "Failed to copy Sample MULTI files for ${abv_name} ${stdy_id}"; return 1; }
aws s3 cp "s3://${SRC_BUCKET}/${abv_lc}/rawData/" "data/" \ --recursive --exclude "*" --no-progress --only-show-errors \ --include "*${stdy_id}*Subject.MULTI*" --include "*${stdy_id}*subject.MULTI*" \ --include "*${stdy_id}*Subject.Multi*" --include "*${stdy_id}*subject.multi*" \ || { error "Failed to copy Subject MULTI files for ${abv_name} ${stdy_id}"; return 1; }
s3_cp "s3://${SRC_BUCKET}/${abv_lc}/data/${abv_uc}_PatientMapping.v2.csv" "data/${abv_uc}_PatientMapping.v2.csv" true }
while IFS=',' read -r abv_name stdy_id data_type stdy_ready stdy_proc; do abv_name="${abv_name%\"}"; abv_name="${abv_name#\"}" stdy_id="${stdy_id%\"}"; stdy_id="${stdy_id#\"}" data_type="${data_type%\"}"; data_type="${data_type#\"}" stdy_ready="${stdy_ready%\"}"; stdy_ready="${stdy_ready#\"}" stdy_proc="${stdy_proc%\"}"; stdy_proc="${stdy_proc#\"}"
if [[ "${data_type,,}" != *g* ]]; then continue fi
if [[ "${stdy_ready,,}" == "yes" && "${stdy_proc,,}" == "no" ]]; then download_study_files "$abv_name" "$stdy_id" fi done < <(tail -n +2 genomic_inputs.csv | csvformat -U 1)
# ----------------------------- # Run generator + upload results # ----------------------------- log "Running IndexFileGenerator.jar" java -jar jars/IndexFileGenerator.jar > logs/index_file_generator.log 2>&1
log "Uploading completed/ -> ${INDEX_OUT_S3}" aws s3 cp "completed/" "${INDEX_OUT_S3}" \ --recursive --exclude "*.csv" \ --no-progress --only-show-errors
log "Done"
